def is_simple_power(x, n):
    """Return True if x is a simple power of n (x == n**int for some integer int >= 0)."""
    if n == 1:
        return x == 1
    if n == -1:
        return x == 1 or x == -1
    p = 1
    for _ in range(200):
        if p == x:
            return True
        if abs(p) > abs(x) * 10 and x != 0:
            break
        p *= n
    return False

